/**
 * LIQUID_GLYPH // PERFORMANCE_MODE
 * Optimized for 60FPS on standard browsers.
 * * OPTIMIZATIONS:
 * - Reduced Grid Density (Bigger Fonts = Bold Design).
 * - DistSq Calculation (Avoids heavy Sqrt math).
 * - Memory Management on Vectors.
 */

let points = [];
let fontSize = 20; // Plus gros pour réduire le nombre d'objets (Gain perf x4)
let cols, rows;
let content = "SYSTEM_OPTIMIZED_60FPS_LIQUID_CORE_"; 

function setup() {
  createCanvas(windowWidth, windowHeight);
  textFont('Courier New');
  textStyle(BOLD);
  noSmooth(); // Gain de perf graphique

  cols = floor(width / fontSize);
  rows = floor(height / fontSize);

  let charIndex = 0;
  for (let y = 0; y < rows; y++) {
    for (let x = 0; x < cols; x++) {
      let char = content.charAt(charIndex % content.length);
      points.push(new KineticPoint(x * fontSize, y * fontSize, char));
      charIndex++;
    }
  }
}

function draw() {
  background(10);

  // Optimisation : On ne crée les vecteurs souris qu'une seule fois par frame
  let mouseXVal = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));
  let mouseYVal = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)));
  let mouseVelX = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));
  let mouseVelY = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)));

  // Boucle optimisée
  for (let i = 0; i < points.length; i++) {
    points[i].update(mouseXVal, mouseYVal, mouseVelX, mouseVelY);
    points[i].display();
  }

  drawFPS();
}

class KineticPoint {
  constructor(x, y, char) {
    // On garde les vecteurs pour la physique, mais on évite d'en créer des nouveaux dans la boucle
    this.pos = createVector(x, y);
    this.target = createVector(x, y);
    this.vel = createVector(0, 0);
    this.acc = createVector(0, 0);
    this.char = char;

    this.maxSpeed = 12;
    this.friction = 0.85; 
    this.elasticity = 0.1; 
  }

  update(mx, my, mvx, mvy) {
    // OPTIMISATION CRITIQUE : Distance au carré (distSq)
    // Évite la racine carrée qui est lente pour le CPU
    let dx = this.pos.x - mx;
    let dy = this.pos.y - my;
    let distSq = dx*dx + dy*dy;
    let radiusSq = 22500; // 150 * 150

    if (distSq < radiusSq) {
      // Force de répulsion manuelle (plus rapide que p5.Vector)
      let forceMag = map(distSq, 0, radiusSq, 10, 0);
      let shock = (Math.abs(mvx) + Math.abs(mvy)) * 0.5;

      // Normalisation manuelle approximative pour la perf
      let len = Math.sqrt(distSq) || 1;
      let dirX = dx / len;
      let dirY = dy / len;

      this.acc.x += dirX * (forceMag + shock);
      this.acc.y += dirY * (forceMag + shock);
    }

    // Ressort (Retour à l'ordre)
    let springX = (this.target.x - this.pos.x) * this.elasticity;
    let springY = (this.target.y - this.pos.y) * this.elasticity;

    this.acc.x += springX;
    this.acc.y += springY;

    // Physique
    this.vel.add(this.acc);
    this.vel.mult(this.friction);
    this.pos.add(this.vel);
    this.acc.set(0, 0);
  }

  display() {
    // On calcule la vitesse au carré pour éviter mag()
    let speedSq = this.vel.x * this.vel.x + this.vel.y * this.vel.y;

    // Rendu conditionnel (Si ça bouge pas, rendu simple)
    if (speedSq < 0.1) {
      fill(80);
      noStroke();
      textSize(fontSize);
      text(this.char, this.pos.x, this.pos.y);
    } else {
      // Rendu complexe seulement si nécessaire
      push();
      translate(this.pos.x + fontSize/2, this.pos.y + fontSize/2);

      // Couleur dynamique
      if (speedSq > 50) fill("#FF0055"); // Rouge violent
      else fill("#00F0FF"); // Cyan actif

      // Rotation simple
      let angle = Math.atan2(this.vel.y, this.vel.x);
      rotate(angle);

      // Glitch char
      let txt = speedSq > 80 ? "+" : this.char;

      textSize(fontSize);
      text(txt, 0, 0);
      pop();
    }
  }
}

function drawFPS() {
  fill(0, 255, 0);
  noStroke();
  textSize(12);
  textAlign(RIGHT, TOP);
  text("FPS: " + floor(frameRate()), width - 10, 10);
  textAlign(LEFT, BASELINE); // Reset align
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  setup();
}

// 1. 免疫 DOM 元素建立導致的看門狗攔截
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || (path.startsWith('http') === false && path.startsWith('data:') === false)) {
            // 當發現是相對路徑或丟失的外部圖片資產時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (this.width === 0 || this.height === 0) {
            try {
                if (typeof this.createGraphics === 'function') {
                    return this.createGraphics(10, 10);
                } else if (typeof createGraphics === 'function') {
                    return createGraphics(10, 10);
                }
            } catch(e) {}
            try {
                if (typeof this.createImage === 'function') {
                    return this.createImage(1, 1);
                }
            } catch(e) {}
            return {
                width: 1,
                height: 1,
                pixels: [0, 0, 0, 0],
                loadPixels: function() {},
                updatePixels: function() {},
                get: function() { return [0, 0, 0, 255]; },
                vertices: []
            };
        }
        try {
            return window._origGet.apply(this, args);
        } catch(e) {
            return {
                width: 1,
                height: 1,
                pixels: [0, 0, 0, 0],
                loadPixels: function() {},
                updatePixels: function() {},
                get: function() { return [0, 0, 0, 255]; },
                vertices: []
            };
        }
    };
}
